// AUTO-GENERATED by scripts/generate-registry-templates.mjs from
// registries/brightlocal/templates/*.jsx — the .jsx files are the authoring
// home (hand-editable full-page scaffolds); do not hand-edit this file.
import type { RegistryTemplate } from "../types";

export const BRIGHTLOCAL_TEMPLATES: readonly RegistryTemplate[] = [
  {
    "id": "citations-hub",
    "label": "Citations Hub",
    "description": "Citations vertical hub: score summary, sync status, directory table, Build Citations CTA.",
    "source": "// Citations Hub — Citations vertical hub: score summary, sync status, directory table, Build Citations CTA.\n//\n// First vertical hub template (the \"lazy prompt\" answer for \"start with\n// the hub page for Citations\"). Same shell mount as page-skeleton.jsx —\n// SidebarProvider > GlobalLayout > GlobalLayoutSidebar > Sidebar compound\n// family — with the Citations nav item active and citations-specific\n// content per rules/05-product-map.md. Edit freely; re-run\n// `node scripts/generate-registry-templates.mjs`.\n\nimport {\n  Avatar,\n  AvatarFallback,\n  Badge,\n  Button,\n  Card,\n  CardContent,\n  GlobalLayout,\n  GlobalLayoutContent,\n  GlobalLayoutContentBody,\n  GlobalLayoutContentHeader,\n  GlobalLayoutSidebar,\n  Logo,\n  Separator,\n  Sidebar,\n  SidebarAccountDropdown,\n  SidebarContent,\n  SidebarFooter,\n  SidebarGroup,\n  SidebarGroupContent,\n  SidebarHeader,\n  SidebarMenu,\n  SidebarMenuButton,\n  SidebarMenuItem,\n  SidebarProvider,\n  SidebarTrigger,\n  Table,\n  TableBody,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n  TypographyH2,\n} from \"@brightlocal/ui-components\";\nimport {\n  Building,\n  Globe,\n  Grid3x3,\n  House,\n  LayoutDashboard,\n  Link as LinkIcon,\n  Menu,\n  Sparkles,\n  Star,\n  Store,\n  TrendingUp,\n} from \"@brightlocal/icons\";\n\n// Sidebar nav icons: 20px (size-5), default stroke — the project's\n// curated convention (rules/05-product-map.md).\nconst TOP_ITEMS = [\n  { id: \"your-locations\", label: \"Your Locations\", icon: House },\n];\n\nconst LOCATION_ITEMS = [\n  { id: \"location-summary\", label: \"Location Summary\", icon: LayoutDashboard },\n  { id: \"ai-insights\", label: \"AI Insights\", icon: Sparkles },\n  { id: \"rankings\", label: \"Rankings\", icon: TrendingUp },\n  { id: \"local-search-grid\", label: \"Local Search Grid\", icon: Grid3x3 },\n  { id: \"citations\", label: \"Citations\", icon: LinkIcon, active: true },\n  { id: \"gbp\", label: \"GBP\", icon: Store },\n  { id: \"reputation-reviews\", label: \"Reputation & Reviews\", icon: Star },\n];\n\nconst TOOL_ITEMS = [\n  { id: \"location-manager\", label: \"Location Manager\", icon: Building },\n  { id: \"white-label\", label: \"White-label\", icon: Globe },\n];\n\nconst DIRECTORIES = [\n  { id: \"google\", name: \"Google Business Profile\", status: \"Live\", nap: \"Accurate\" },\n  { id: \"bing\", name: \"Bing Places\", status: \"Live\", nap: \"Accurate\" },\n  { id: \"apple\", name: \"Apple Maps\", status: \"Sync issue\", nap: \"Phone mismatch\" },\n  { id: \"yelp\", name: \"Yelp\", status: \"Live\", nap: \"Accurate\" },\n  { id: \"facebook\", name: \"Facebook\", status: \"Pending\", nap: \"—\" },\n];\n\nfunction NavGroup({ items }) {\n  return (\n    <SidebarGroup>\n      <SidebarGroupContent>\n        <SidebarMenu>\n          {items.map((item) => (\n            <SidebarMenuItem key={item.id}>\n              <SidebarMenuButton\n                dataHook={`nav-${item.id}`}\n                isActive={item.active}\n              >\n                {item.icon ? <item.icon className=\"size-5\" /> : null}\n                <span>{item.label}</span>\n              </SidebarMenuButton>\n            </SidebarMenuItem>\n          ))}\n        </SidebarMenu>\n      </SidebarGroupContent>\n    </SidebarGroup>\n  );\n}\n\nexport default function CitationsHub() {\n  return (\n    <SidebarProvider dataHook=\"citations-hub-sidebar-provider\" defaultOpen>\n      <GlobalLayout dataHook=\"global-layout\">\n        <GlobalLayoutSidebar dataHook=\"global-layout-sidebar\">\n          <Sidebar dataHook=\"app-sidebar\">\n            <SidebarHeader>\n              <Logo className=\"h-6\" dataHook=\"sidebar-logo\" />\n            </SidebarHeader>\n            <SidebarContent dataHook=\"sidebar-content\">\n              <NavGroup items={TOP_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-1\" />\n              <NavGroup items={LOCATION_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-2\" />\n              <NavGroup items={TOOL_ITEMS} />\n            </SidebarContent>\n            <SidebarFooter dataHook=\"sidebar-footer\">\n              <SidebarMenu>\n                <SidebarMenuItem>\n                  <SidebarAccountDropdown\n                    dataHook=\"sidebar-account-dropdown\"\n                    name=\"Andy Smith\"\n                    email=\"andy@acmecorp.com\"\n                    avatar={\n                      <Avatar dataHook=\"sidebar-user-avatar\">\n                        <AvatarFallback>AS</AvatarFallback>\n                      </Avatar>\n                    }\n                    menuGroups={[\n                      [\n                        { label: \"Account settings\" },\n                        { label: \"Notification preferences\" },\n                      ],\n                      [{ label: \"Log out\" }],\n                    ]}\n                    side=\"top\"\n                    align=\"end\"\n                  />\n                </SidebarMenuItem>\n              </SidebarMenu>\n            </SidebarFooter>\n          </Sidebar>\n        </GlobalLayoutSidebar>\n\n        <GlobalLayoutContent dataHook=\"global-layout-content\">\n          {/* Mobile top bar — hamburger (≡, matching live) + logo below\n              lg; 44px touch target, 20px glyph, no border (matching\n              live). SidebarTrigger opens the DS's built-in mobile\n              sheet. */}\n          <header className=\"flex items-center gap-1 px-1 py-1 lg:hidden\">\n            <SidebarTrigger dataHook=\"mobile-sidebar-trigger\" className=\"size-11\">\n              <Menu className=\"size-5\" />\n            </SidebarTrigger>\n            <Logo className=\"h-6\" dataHook=\"mobile-logo\" />\n          </header>\n          <GlobalLayoutContentHeader dataHook=\"page-header\">\n            <div className=\"flex min-w-0 items-center gap-3\">\n              <Avatar dataHook=\"location-avatar\">\n                <AvatarFallback>BF</AvatarFallback>\n              </Avatar>\n              <div className=\"min-w-0\">\n                <TypographyH2 dataHook=\"page-title\">Citations</TypographyH2>\n                <div className=\"text-muted-foreground flex flex-wrap items-center gap-2 text-sm\">\n                  <span>Blackberry Farm Park · Lewes, BN8 6JD</span>\n                  <Badge dataHook=\"location-status\">Active</Badge>\n                </div>\n              </div>\n            </div>\n            <Button dataHook=\"build-citations-button\">Build Citations</Button>\n          </GlobalLayoutContentHeader>\n\n          <GlobalLayoutContentBody dataHook=\"page-body\">\n            <div className=\"flex flex-col gap-6\">\n              {/* Score summary row */}\n              <div className=\"grid gap-4 sm:grid-cols-3\">\n                <Card variant=\"filled\" dataHook=\"stat-citations-found\">\n                  <CardContent>\n                    <p className=\"text-muted-foreground text-sm\">\n                      Citations found\n                    </p>\n                    <p className=\"text-2xl font-bold\">53 / 60</p>\n                    <p className=\"text-muted-foreground text-xs\">\n                      7 opportunities available\n                    </p>\n                  </CardContent>\n                </Card>\n                <Card variant=\"filled\" dataHook=\"stat-nap-accuracy\">\n                  <CardContent>\n                    <p className=\"text-muted-foreground text-sm\">\n                      NAP accuracy\n                    </p>\n                    <p className=\"text-2xl font-bold\">92%</p>\n                    <p className=\"text-muted-foreground text-xs\">\n                      1 listing needs attention\n                    </p>\n                  </CardContent>\n                </Card>\n                <Card variant=\"filled\" dataHook=\"stat-sync-status\">\n                  <CardContent>\n                    <p className=\"text-muted-foreground text-sm\">\n                      Listings sync\n                    </p>\n                    <p className=\"text-2xl font-bold\">4 / 5</p>\n                    <p className=\"text-muted-foreground text-xs\">\n                      Last synced 13 Jul 2026\n                    </p>\n                  </CardContent>\n                </Card>\n              </div>\n\n              {/* Directory table */}\n              <div>\n                <TypographyH2 dataHook=\"directories-title\">\n                  Directories\n                </TypographyH2>\n                <p className=\"text-muted-foreground text-sm\">\n                  Where your business listing appears and how accurate it is.\n                </p>\n              </div>\n              <Card variant=\"filled\" className=\"max-w-none\" dataHook=\"directories-card\">\n                <CardContent>\n                  <Table dataHook=\"directories-table\">\n                    <TableHeader>\n                      <TableRow>\n                        <TableHead>Directory</TableHead>\n                        <TableHead>Status</TableHead>\n                        <TableHead>NAP accuracy</TableHead>\n                      </TableRow>\n                    </TableHeader>\n                    <TableBody>\n                      {DIRECTORIES.map((d) => (\n                        <TableRow key={d.id} dataHook={`directory-${d.id}-row`}>\n                          <TableCell>{d.name}</TableCell>\n                          <TableCell>\n                            <Badge dataHook={`directory-${d.id}-status`}>\n                              {d.status}\n                            </Badge>\n                          </TableCell>\n                          <TableCell>{d.nap}</TableCell>\n                        </TableRow>\n                      ))}\n                    </TableBody>\n                  </Table>\n                </CardContent>\n              </Card>\n            </div>\n          </GlobalLayoutContentBody>\n        </GlobalLayoutContent>\n      </GlobalLayout>\n    </SidebarProvider>\n  );\n}"
  },
  {
    "id": "hub-page",
    "label": "Hub Page",
    "description": "Location hub: proposal shell + hub header + a responsive grid of HubStatCards linking into each module.",
    "source": "// Hub Page — Location hub: proposal shell + hub header + a responsive grid of HubStatCards linking into each module.\n//\n// FIRST SCREEN of the @brightlocal/proposal era (STUDIO-FLOWS M0): the\n// shell, sidenav, page header and hub cards live in the shared registry\n// module — packages/studio/registries/brightlocal/lib/proposal.jsx —\n// and this template is JUST THE PAGE. Editing proposal.jsx (nav IA,\n// card anatomy, shell presets) updates every screen that imports it;\n// screens still carrying in-file copies stay as they are and migrate\n// on regen. Data rides the ProposalDataProvider seam: the defaults ARE\n// the demo data, so this screen mounts nothing — wrap in\n// <ProposalDataProvider data={{...}}> to re-skin account/user/location/\n// metrics in one move (\"switch the data and it would be magic\").\n// Hand-authored — safe from harvest re-runs. Edit freely; re-run\n// `node scripts/generate-registry-templates.mjs`.\n\nimport {\n  SidebarProvider,\n  SidebarTrigger,\n  GlobalLayoutContentBody,\n  Logo,\n} from \"@brightlocal/ui-components\";\nimport {\n  Globe,\n  Grid3x3,\n  Link,\n  Menu,\n  Star,\n  Store,\n  TrendingUp,\n} from \"@brightlocal/icons\";\nimport {\n  AppLayoutShell,\n  ProposalSidebar,\n  PageHeader,\n  HubStatCard,\n  HubHeroCard,\n  ProposalDataProvider,\n} from \"@brightlocal/proposal\";\n\n// ─── Project data — the per-project wiring layer ─────────────────────\n// navLinks map nav row ids → screen names (STUDIO-FLOWS): flows live in\n// DATA, stable per project, editable without touching the IA. Providers\n// STACK, so the tweaker's dataset switch keeps these links. Add area\n// data (tables, insights) here as screens need it.\nconst PROJECT_DATA = {\n  navLinks: {\n    \"rankings-table\": \"Rankings Table\",\n    // Keyword rows are generated by buildProposalSections with stable\n    // index ids — link them all into the Local Search Grid screen.\n    // Unresolvable targets no-op (a project without that screen loses\n    // nothing).\n    \"local-search-grid-keyword-0\": \"Local Search Grid\",\n    \"local-search-grid-keyword-1\": \"Local Search Grid\",\n    \"local-search-grid-keyword-2\": \"Local Search Grid\",\n    \"local-search-grid-keyword-3\": \"Local Search Grid\",\n    \"local-search-grid-keyword-4\": \"Local Search Grid\",\n  },\n};\n\nexport default function App() {\n  return (\n    <ProposalDataProvider data={PROJECT_DATA}>\n    <SidebarProvider dataHook=\"switcher-sidebar-provider\" defaultOpen>\n      {/* Layout knobs are LITERAL props so the inspector can edit them —\n          select the shell (click the page background) and flip\n          flush / stickyHeader / pinnedSidebar / sidebarTone. */}\n      <AppLayoutShell\n        flush={true}\n        stickyHeader={true}\n        pinnedSidebar={true}\n        sidebarTone=\"white\"\n        // activeId states WHICH PAGE THIS IS: the hub is the location's\n        // landing, matching no nav row — nothing highlights, trails stay\n        // collapsed. A module screen passes its row id instead\n        // (activeId=\"rankings-table\" on the Rankings Table screen).\n        sidebar={<ProposalSidebar dataHook=\"app-sidebar\" activeId=\"location-hub\" />}\n        header={\n          // meta omitted ON PURPOSE — PageHeader's default meta is\n          // data-bound (location name + status from useProposalData,\n          // read at render position so dataset switches reach it).\n          <PageHeader\n            breadcrumbs={[{ label: \"Your Locations\", href: \"#\" }]}\n            title=\"Location Hub\"\n            dataHook=\"page-header\"\n          />\n        }\n        mobileBar={\n          <header className=\"flex items-center gap-1 px-1 py-1 lg:hidden\">\n            <SidebarTrigger dataHook=\"mobile-sidebar-trigger\" className=\"size-11\">\n              <Menu className=\"size-5\" />\n            </SidebarTrigger>\n            <Logo className=\"h-6\" dataHook=\"mobile-logo\" />\n          </header>\n        }\n        dataHook=\"app-layout\"\n      >\n        <GlobalLayoutContentBody dataHook=\"page-body\">\n          <HubHeroCard\n            title=\"Get more from your local presence\"\n            description=\"AI Insights reviews your listings, rankings and reviews together and tells you the three things to fix first.\"\n            primaryCta=\"Run AI Insights\"\n            primaryHook=\"hub-hero-primary\"\n            secondaryCta=\"See how it works\"\n            secondaryHook=\"hub-hero-secondary\"\n            dataHook=\"hub-hero-card\"\n          />\n          {/* Tracks own the sizing — Card bakes max-w-[400px], hence\n              max-w-none inside HubStatCard. metricKey = full data\n              binding: metric/delta/description come from\n              data.metrics.<key> at render position, so dataset\n              switches (tweaker Data row, ProposalDataProvider) re-skin\n              every card live. */}\n          <div className=\"mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-3\">\n            <HubStatCard\n              icon={Star}\n              title=\"Reviews\"\n              metricKey=\"reviews\"\n              ctaHook=\"hub-reviews-cta\"\n              dataHook=\"hub-reviews-card\"\n            />\n            <HubStatCard\n              icon={TrendingUp}\n              title=\"Rankings\"\n              metricKey=\"rankings\"\n              goto=\"Rankings Table\"\n              ctaHook=\"hub-rankings-cta\"\n              dataHook=\"hub-rankings-card\"\n            />\n            <HubStatCard\n              icon={Link}\n              title=\"Citations\"\n              metricKey=\"citations\"\n              ctaHook=\"hub-citations-cta\"\n              dataHook=\"hub-citations-card\"\n            />\n            <HubStatCard\n              icon={Grid3x3}\n              title=\"Local Search Grid\"\n              metricKey=\"localSearchGrid\"\n              goto=\"Local Search Grid\"\n              ctaHook=\"hub-local-search-grid-cta\"\n              dataHook=\"hub-local-search-grid-card\"\n            />\n            <HubStatCard\n              icon={Store}\n              title=\"GBP Manager\"\n              metricKey=\"gbpManager\"\n              ctaHook=\"hub-gbp-cta\"\n              dataHook=\"hub-gbp-card\"\n            />\n            <HubStatCard\n              icon={Globe}\n              title=\"Website SEO\"\n              metricKey=\"websiteSeo\"\n              ctaHook=\"hub-seo-cta\"\n              dataHook=\"hub-seo-card\"\n            />\n          </div>\n        </GlobalLayoutContentBody>\n      </AppLayoutShell>\n    </SidebarProvider>\n    </ProposalDataProvider>\n  );\n}"
  },
  {
    "id": "location-dashboard",
    "label": "Location Dashboard",
    "description": "Full location overview: identity card, score, customer actions, rankings tabs.",
    "source": "// Location Dashboard — Full location overview: identity card, score, customer actions, rankings tabs.\n//\n// Hand-authored scaffold reconstructed from BrightLocal's Lab\n// \"Location Dashboard\" composition (storybook lab-location-dashboard —\n// its story source is minified upstream, so this is the editable\n// recreation; see BYODS-BRIGHTLOCAL-PLAN.md client findings).\n// Everything below is verified-rendering BL vocabulary. Edit freely —\n// this file is the authoring home; re-run\n// `node scripts/generate-registry-templates.mjs` after changes.\n\nimport {\n  Avatar,\n  AvatarFallback,\n  Badge,\n  Breadcrumb,\n  BreadcrumbItem,\n  BreadcrumbLink,\n  BreadcrumbList,\n  BreadcrumbPage,\n  BreadcrumbSeparator,\n  Button,\n  Card,\n  CardAction,\n  CardContent,\n  CardDescription,\n  CardFooter,\n  CardHeader,\n  CardTitle,\n  GlobalLayout,\n  GlobalLayoutContent,\n  GlobalLayoutContentBody,\n  GlobalLayoutContentHeader,\n  GlobalLayoutSidebar,\n  Logo,\n  Separator,\n  Sidebar,\n  SidebarAccountDropdown,\n  SidebarContent,\n  SidebarFooter,\n  SidebarGroup,\n  SidebarGroupContent,\n  SidebarHeader,\n  SidebarMenu,\n  SidebarMenuButton,\n  SidebarMenuItem,\n  SidebarProvider,\n  SidebarTrigger,\n  Tabs,\n  TabsContent,\n  TabsList,\n  TabsTrigger,\n} from \"@brightlocal/ui-components\";\nimport {\n  Building,\n  Globe,\n  Grid3x3,\n  House,\n  LayoutDashboard,\n  Link as LinkIcon,\n  Menu,\n  Sparkles,\n  Star,\n  Store,\n  TrendingUp,\n} from \"@brightlocal/icons\";\n\nconst TOP_ITEMS = [\n  { id: \"your-locations\", label: \"Your Locations\", icon: House },\n];\n\nconst LOCATION_ITEMS = [\n  {\n    id: \"location-summary\",\n    label: \"Location Summary\",\n    icon: LayoutDashboard,\n    active: true,\n  },\n  { id: \"ai-insights\", label: \"AI Insights\", icon: Sparkles },\n  { id: \"rankings\", label: \"Rankings\", icon: TrendingUp },\n  { id: \"local-search-grid\", label: \"Local Search Grid\", icon: Grid3x3 },\n  { id: \"citations\", label: \"Citations\", icon: LinkIcon },\n  { id: \"gbp\", label: \"GBP\", icon: Store },\n  { id: \"reputation-reviews\", label: \"Reputation & Reviews\", icon: Star },\n];\n\nconst TOOL_ITEMS = [\n  { id: \"location-manager\", label: \"Location Manager\", icon: Building },\n  { id: \"white-label\", label: \"White-label\", icon: Globe },\n];\n\nfunction NavGroup({ items }) {\n  return (\n    <SidebarGroup>\n      <SidebarGroupContent>\n        <SidebarMenu>\n          {items.map((item) => (\n            <SidebarMenuItem key={item.id}>\n              <SidebarMenuButton\n                dataHook={`nav-${item.id}`}\n                isActive={item.active}\n              >\n                {item.icon ? <item.icon className=\"size-5\" /> : null}\n                <span>{item.label}</span>\n              </SidebarMenuButton>\n            </SidebarMenuItem>\n          ))}\n        </SidebarMenu>\n      </SidebarGroupContent>\n    </SidebarGroup>\n  );\n}\n\nexport default function LocationDashboard() {\n  return (\n    <SidebarProvider dataHook=\"location-dashboard-sidebar-provider\" defaultOpen>\n      <GlobalLayout dataHook=\"global-layout\">\n        <GlobalLayoutSidebar dataHook=\"global-layout-sidebar\">\n          <Sidebar dataHook=\"app-sidebar\">\n            <SidebarHeader>\n              <Logo className=\"h-6\" dataHook=\"sidebar-logo\" />\n            </SidebarHeader>\n            <SidebarContent dataHook=\"sidebar-content\">\n              <NavGroup items={TOP_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-1\" />\n              <NavGroup items={LOCATION_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-2\" />\n              <NavGroup items={TOOL_ITEMS} />\n            </SidebarContent>\n            <SidebarFooter dataHook=\"sidebar-footer\">\n              <SidebarMenu>\n                <SidebarMenuItem>\n                  <SidebarAccountDropdown\n                    dataHook=\"sidebar-account-dropdown\"\n                    name=\"Andy Smith\"\n                    email=\"andy@acmecorp.com\"\n                    avatar={\n                      <Avatar dataHook=\"sidebar-user-avatar\">\n                        <AvatarFallback>AS</AvatarFallback>\n                      </Avatar>\n                    }\n                    menuGroups={[\n                      [\n                        { label: \"Account settings\" },\n                        { label: \"Notification preferences\" },\n                      ],\n                      [{ label: \"Log out\" }],\n                    ]}\n                    side=\"top\"\n                    align=\"end\"\n                  />\n                </SidebarMenuItem>\n              </SidebarMenu>\n            </SidebarFooter>\n          </Sidebar>\n        </GlobalLayoutSidebar>\n\n        <GlobalLayoutContent dataHook=\"global-layout-content\">\n          {/* Mobile top bar — see rules/05-product-map.md. */}\n          <header className=\"flex items-center gap-1 px-1 py-1 lg:hidden\">\n            <SidebarTrigger dataHook=\"mobile-sidebar-trigger\" className=\"size-11\">\n              <Menu className=\"size-5\" />\n            </SidebarTrigger>\n            <Logo className=\"h-6\" dataHook=\"mobile-logo\" />\n          </header>\n\n          {/* Page header — breadcrumb + date scope (this page keeps its\n              identity in the body card, so the header stays the\n              breadcrumb bar like the live dashboard). */}\n          <GlobalLayoutContentHeader dataHook=\"page-header\">\n            <Breadcrumb dataHook=\"location-breadcrumb\">\n              <BreadcrumbList>\n                <BreadcrumbItem>\n                  <BreadcrumbLink href=\"#\">All locations</BreadcrumbLink>\n                </BreadcrumbItem>\n              </BreadcrumbList>\n            </Breadcrumb>\n            <Button variant=\"outline\" dataHook=\"date-scope-button\">\n              April 23rd, 2026\n            </Button>\n          </GlobalLayoutContentHeader>\n\n          <GlobalLayoutContentBody dataHook=\"page-body\">\n            <div className=\"grid gap-6 lg:grid-cols-3\">\n        {/* Identity card */}\n        <Card variant=\"filled\" dataHook=\"location-card\">\n          <CardHeader dataHook=\"location-card-header\">\n            <CardTitle>Bailiffscourt Hotel &amp; Spa</CardTitle>\n            <CardDescription>★ 4.4 (764 reviews)</CardDescription>\n            <CardAction>\n              <Badge dataHook=\"location-status\">Active</Badge>\n            </CardAction>\n          </CardHeader>\n          <CardContent>\n            <div className=\"grid gap-1 text-sm text-muted-foreground\">\n              <span>Littlehampton, BN17 5RW</span>\n              <span>Hotel</span>\n              <span>+44 1903 723511</span>\n            </div>\n          </CardContent>\n          <CardFooter>\n            <Button variant=\"outline\" dataHook=\"edit-location-button\">\n              Edit location\n            </Button>\n          </CardFooter>\n        </Card>\n\n        {/* Location score */}\n        <Card variant=\"filled\" dataHook=\"location-score-card\">\n          <CardHeader>\n            <CardTitle>Location Score</CardTitle>\n          </CardHeader>\n          <CardContent>\n            <div className=\"flex flex-col items-center gap-2 py-2\">\n              <span className=\"text-6xl font-semibold\" data-hook=\"location-score-value\">\n                58\n              </span>\n              <Badge dataHook=\"location-score-delta\">+3 since April 16</Badge>\n              <p className=\"pt-2 text-center text-sm text-muted-foreground\">\n                You&rsquo;re ranking #1 locally for &ldquo;hotel spa\n                retreat&rdquo; and outperforming 6 of your 10 nearest\n                competitors on website authority.\n              </p>\n            </div>\n          </CardContent>\n        </Card>\n\n        {/* Customer actions — nested condensed stat tiles */}\n        <Card variant=\"filled\" dataHook=\"customer-actions-card\">\n          <CardHeader dataHook=\"customer-actions-header\">\n            <CardTitle>Customer actions</CardTitle>\n            <CardDescription>This month vs last month</CardDescription>\n          </CardHeader>\n          <CardContent>\n            <div className=\"grid gap-3\">\n              <Card density=\"condensed\" variant=\"filled\" dataHook=\"call-clicks-tile\">\n                <CardContent>\n                  <p className=\"text-sm text-muted-foreground\">Call clicks</p>\n                  <div className=\"flex items-baseline justify-between\">\n                    <span className=\"text-2xl font-semibold\">312</span>\n                    <Badge dataHook=\"call-clicks-delta\">↑ 8%</Badge>\n                  </div>\n                </CardContent>\n              </Card>\n              <Card density=\"condensed\" variant=\"filled\" dataHook=\"website-clicks-tile\">\n                <CardContent>\n                  <p className=\"text-sm text-muted-foreground\">Website clicks</p>\n                  <div className=\"flex items-baseline justify-between\">\n                    <span className=\"text-2xl font-semibold\">1,847</span>\n                    <Badge dataHook=\"website-clicks-delta\">↑ 14%</Badge>\n                  </div>\n                </CardContent>\n              </Card>\n              <Card density=\"condensed\" variant=\"filled\" dataHook=\"direction-requests-tile\">\n                <CardContent>\n                  <p className=\"text-sm text-muted-foreground\">Direction requests</p>\n                  <div className=\"flex items-baseline justify-between\">\n                    <span className=\"text-2xl font-semibold\">428</span>\n                    <Badge variant=\"destructive\" dataHook=\"direction-requests-delta\">\n                      ↓ 3%\n                    </Badge>\n                  </div>\n                </CardContent>\n              </Card>\n            </div>\n          </CardContent>\n        </Card>\n\n        {/* Rankings — full-width tabs section */}\n        <Card variant=\"filled\" className=\"max-w-none lg:col-span-3\" dataHook=\"visibility-card\">\n          <CardHeader dataHook=\"visibility-header\">\n            <CardTitle>Visibility</CardTitle>\n            <CardDescription>\n              Rank tracking across Google Search, Maps, and citations.\n            </CardDescription>\n            <CardAction>\n              <Button dataHook=\"run-audit-button\">Run new audit</Button>\n            </CardAction>\n          </CardHeader>\n          <CardContent>\n            <Tabs defaultValue=\"rankings\" dataHook=\"visibility-tabs\">\n              <TabsList>\n                <TabsTrigger value=\"rankings\" dataHook=\"tab-rankings\">\n                  Rank Tracking\n                </TabsTrigger>\n                <TabsTrigger value=\"citations\" dataHook=\"tab-citations\">\n                  Citation Health\n                </TabsTrigger>\n              </TabsList>\n              <TabsContent value=\"rankings\">\n                <div className=\"grid gap-3 py-4 sm:grid-cols-3\">\n                  <Card density=\"condensed\" variant=\"filled\" dataHook=\"avg-position-tile\">\n                    <CardContent>\n                      <p className=\"text-sm text-muted-foreground\">Avg. ranking position</p>\n                      <div className=\"flex items-baseline justify-between\">\n                        <span className=\"text-2xl font-semibold\">2.2</span>\n                        <Badge dataHook=\"avg-position-delta\">↑ 0.9 better</Badge>\n                      </div>\n                    </CardContent>\n                  </Card>\n                  <Card density=\"condensed\" variant=\"filled\" dataHook=\"top3-tile\">\n                    <CardContent>\n                      <p className=\"text-sm text-muted-foreground\">Keywords in top 3</p>\n                      <div className=\"flex items-baseline justify-between\">\n                        <span className=\"text-2xl font-semibold\">28</span>\n                        <Badge dataHook=\"top3-delta\">↑ 4 keywords</Badge>\n                      </div>\n                    </CardContent>\n                  </Card>\n                  <Card density=\"condensed\" variant=\"filled\" dataHook=\"citations-tile\">\n                    <CardContent>\n                      <p className=\"text-sm text-muted-foreground\">Citations found</p>\n                      <div className=\"flex items-baseline justify-between\">\n                        <span className=\"text-2xl font-semibold\">53 / 60</span>\n                        <Badge variant=\"outline\" dataHook=\"citations-status\">\n                          Action needed\n                        </Badge>\n                      </div>\n                    </CardContent>\n                  </Card>\n                </div>\n              </TabsContent>\n              <TabsContent value=\"citations\">\n                <p className=\"py-6 text-sm text-muted-foreground\">\n                  Citation health details — replace with a DataTable of\n                  directories once the blocks source lands.\n                </p>\n              </TabsContent>\n            </Tabs>\n          </CardContent>\n        </Card>\n            </div>\n          </GlobalLayoutContentBody>\n        </GlobalLayoutContent>\n      </GlobalLayout>\n    </SidebarProvider>\n  );\n}"
  },
  {
    "id": "location-summary",
    "label": "Location Summary",
    "description": "The near-product location summary: app shell + canonical photo header + welcome/insights card, Location Score, foundation cards.",
    "source": "// Location Summary — The near-product location summary: app shell + canonical photo header + welcome/insights card, Location Score, foundation cards.\n//\n// Composed from the verified building blocks: page-skeleton's app shell\n// (sidebar + mobile bar + Andy Smith persona), the location-page-header\n// recipe (hand-authored from the LIVE platform DOM), and the summary\n// body from the live \"Welcome back\" page (14 Jul screenshot): welcome\n// card + insights CTA, Location Score with Foundation/Visibility\n// sub-scores, and the Build-your-foundation cards with per-metric\n// progress rows. Edit freely; re-run\n// `node scripts/generate-registry-templates.mjs`.\n\nimport {\n  AspectRatio,\n  Avatar,\n  AvatarFallback,\n  Badge,\n  Button,\n  Card,\n  CardContent,\n  GlobalLayout,\n  GlobalLayoutContent,\n  GlobalLayoutContentBody,\n  GlobalLayoutContentHeader,\n  GlobalLayoutSidebar,\n  Logo,\n  Progress,\n  Separator,\n  Sidebar,\n  SidebarAccountDropdown,\n  SidebarContent,\n  SidebarFooter,\n  SidebarGroup,\n  SidebarGroupContent,\n  SidebarHeader,\n  SidebarMenu,\n  SidebarMenuButton,\n  SidebarMenuItem,\n  SidebarProvider,\n  SidebarTrigger,\n  TypographyH2,\n  TypographySmall,\n} from \"@brightlocal/ui-components\";\nimport {\n  Building,\n  Globe,\n  Grid3x3,\n  House,\n  LayoutDashboard,\n  Link as LinkIcon,\n  MapPin,\n  Menu,\n  Sparkles,\n  Star,\n  Store,\n  TrendingUp,\n} from \"@brightlocal/icons\";\n\nconst TOP_ITEMS = [\n  { id: \"your-locations\", label: \"Your Locations\", icon: House },\n];\n\nconst LOCATION_ITEMS = [\n  {\n    id: \"location-summary\",\n    label: \"Location Summary\",\n    icon: LayoutDashboard,\n    active: true,\n  },\n  { id: \"ai-insights\", label: \"AI Insights\", icon: Sparkles },\n  { id: \"rankings\", label: \"Rankings\", icon: TrendingUp },\n  { id: \"local-search-grid\", label: \"Local Search Grid\", icon: Grid3x3 },\n  { id: \"citations\", label: \"Citations\", icon: LinkIcon },\n  { id: \"gbp\", label: \"GBP\", icon: Store },\n  { id: \"reputation-reviews\", label: \"Reputation & Reviews\", icon: Star },\n];\n\nconst TOOL_ITEMS = [\n  { id: \"location-manager\", label: \"Location Manager\", icon: Building },\n  { id: \"white-label\", label: \"White-label\", icon: Globe },\n];\n\nconst WEBSITE_METRICS = [\n  { id: \"conversion-ux\", label: \"Conversion UX\", score: 15 },\n  { id: \"keyword-coverage\", label: \"Keyword coverage\", score: 100 },\n  { id: \"page-optimization\", label: \"Page optimization\", score: 100 },\n  { id: \"technical-health\", label: \"Technical health\", score: 60 },\n  { id: \"local-intent\", label: \"Local intent & linking\", score: 14 },\n];\n\nconst GBP_METRICS = [\n  { id: \"activity\", label: \"Activity & freshness\", score: 100 },\n  { id: \"conversion-tracking\", label: \"Conversion tracking\", score: 50 },\n  { id: \"profile-completeness\", label: \"Profile completeness\", score: 60 },\n  { id: \"nap-alignment\", label: \"NAP alignment\", score: 30 },\n  { id: \"category-accuracy\", label: \"Category & service accuracy\", score: 30 },\n];\n\nfunction NavGroup({ items }) {\n  return (\n    <SidebarGroup>\n      <SidebarGroupContent>\n        <SidebarMenu>\n          {items.map((item) => (\n            <SidebarMenuItem key={item.id}>\n              <SidebarMenuButton\n                dataHook={`nav-${item.id}`}\n                isActive={item.active}\n              >\n                {item.icon ? <item.icon className=\"size-5\" /> : null}\n                <span>{item.label}</span>\n              </SidebarMenuButton>\n            </SidebarMenuItem>\n          ))}\n        </SidebarMenu>\n      </SidebarGroupContent>\n    </SidebarGroup>\n  );\n}\n\nfunction MetricRow({ id, label, score }) {\n  return (\n    <div className=\"flex items-center gap-3\" data-hook={`metric-${id}-row`}>\n      <span className=\"w-40 shrink-0 text-sm\">{label}</span>\n      <Progress value={score} className=\"h-2 flex-1\" dataHook={`metric-${id}-progress`} />\n      <span className=\"text-muted-foreground w-16 shrink-0 text-right text-sm tabular-nums\">\n        {score}/100\n      </span>\n    </div>\n  );\n}\n\nexport default function LocationSummary() {\n  return (\n    <SidebarProvider dataHook=\"location-summary-sidebar-provider\" defaultOpen>\n      <GlobalLayout dataHook=\"global-layout\">\n        <GlobalLayoutSidebar dataHook=\"global-layout-sidebar\">\n          <Sidebar dataHook=\"app-sidebar\">\n            <SidebarHeader>\n              <Logo className=\"h-6\" dataHook=\"sidebar-logo\" />\n            </SidebarHeader>\n            <SidebarContent dataHook=\"sidebar-content\">\n              <NavGroup items={TOP_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-1\" />\n              <NavGroup items={LOCATION_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-2\" />\n              <NavGroup items={TOOL_ITEMS} />\n            </SidebarContent>\n            <SidebarFooter dataHook=\"sidebar-footer\">\n              <SidebarMenu>\n                <SidebarMenuItem>\n                  <SidebarAccountDropdown\n                    dataHook=\"sidebar-account-dropdown\"\n                    name=\"Andy Smith\"\n                    email=\"andy@acmecorp.com\"\n                    avatar={\n                      <Avatar dataHook=\"sidebar-user-avatar\">\n                        <AvatarFallback>AS</AvatarFallback>\n                      </Avatar>\n                    }\n                    menuGroups={[\n                      [\n                        { label: \"Account settings\" },\n                        { label: \"Notification preferences\" },\n                      ],\n                      [{ label: \"Log out\" }],\n                    ]}\n                    side=\"top\"\n                    align=\"end\"\n                  />\n                </SidebarMenuItem>\n              </SidebarMenu>\n            </SidebarFooter>\n          </Sidebar>\n        </GlobalLayoutSidebar>\n\n        <GlobalLayoutContent dataHook=\"global-layout-content\">\n          {/* Mobile top bar — see rules/05-product-map.md. */}\n          <header className=\"flex items-center gap-1 px-1 py-1 lg:hidden\">\n            <SidebarTrigger dataHook=\"mobile-sidebar-trigger\" className=\"size-11\">\n              <Menu className=\"size-5\" />\n            </SidebarTrigger>\n            <Logo className=\"h-6\" dataHook=\"mobile-logo\" />\n          </header>\n\n          {/* Canonical page header — the location-page-header recipe. */}\n          <GlobalLayoutContentHeader dataHook=\"page-header\">\n            <div className=\"flex w-full flex-col gap-2 md:flex-row md:items-center md:justify-between\">\n              <div\n                className=\"flex w-full flex-col gap-4 md:flex-row md:items-center\"\n                data-hook=\"location-header-card\"\n              >\n                <div className=\"w-full md:hidden\">\n                  <AspectRatio dataHook=\"location-header-card-photo-sm\" ratio={21 / 9}>\n                    <img\n                      alt=\"Brighton Bierhaus location photo\"\n                      className=\"h-full w-full rounded-xl object-cover\"\n                      src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=800&q=80\"\n                    />\n                  </AspectRatio>\n                </div>\n                <div className=\"hidden w-24 shrink-0 md:block\">\n                  <AspectRatio dataHook=\"location-header-card-photo-lg\" ratio={16 / 10}>\n                    <img\n                      alt=\"Brighton Bierhaus location photo\"\n                      className=\"h-full w-full rounded-xl object-cover\"\n                      src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=400&q=80\"\n                    />\n                  </AspectRatio>\n                </div>\n                <div className=\"flex flex-col gap-1.5\">\n                  <TypographyH2 dataHook=\"location-business-name\">\n                    Brighton Bierhaus\n                  </TypographyH2>\n                  <div className=\"flex flex-wrap items-center gap-x-3 gap-y-1 text-sm text-muted-foreground\">\n                    <span className=\"flex items-center gap-1.5\">\n                      <MapPin className=\"size-3.5 shrink-0\" />\n                      <span>Brighton and Hove, BN2 0JB</span>\n                    </span>\n                    <span className=\"flex items-center gap-1.5\">\n                      <Star className=\"size-3.5 fill-yellow-400 stroke-yellow-400\" />\n                      <span>4.6 (539 reviews)</span>\n                    </span>\n                    <span className=\"basis-full md:basis-auto\">\n                      {/* Status badge — success tokens via className: the DS\n                          ships no success variant (rules/90-audit.md). */}\n                      <Badge\n                        dataHook=\"location-status-badge-active\"\n                        className=\"border-transparent bg-success-background text-success-foreground\"\n                      >\n                        Active\n                      </Badge>\n                    </span>\n                  </div>\n                </div>\n              </div>\n              <div className=\"md:shrink-0\">\n                <TypographySmall dataHook=\"location-last-updated\">\n                  Last updated: 14/07/26\n                </TypographySmall>\n              </div>\n            </div>\n          </GlobalLayoutContentHeader>\n\n          <GlobalLayoutContentBody dataHook=\"page-body\">\n            <div className=\"flex flex-col gap-6\">\n              {/* Welcome + Location Score — the welcome-insights-card\n                  recipe (full width, donut ring, Sparkles CTA). Copied,\n                  not included: screens are self-contained JSX — the\n                  recipe file is the authoring source; re-sync on change. */}\n              <Card variant=\"filled\" className=\"w-full max-w-none\" dataHook=\"welcome-card\">\n                <CardContent>\n                  <div className=\"grid items-center gap-8 lg:grid-cols-[1fr_auto]\">\n                    <div className=\"flex flex-col gap-3\">\n                      <TypographyH2 dataHook=\"welcome-title\">\n                        Welcome back, Andy Smith\n                      </TypographyH2>\n                      <p className=\"text-muted-foreground max-w-prose text-sm\">\n                        Brighton Bierhaus has a strong Google presence with an\n                        excellent rating and plenty of photos. The fastest\n                        gains now are to fix website blockers, strengthen\n                        local signals on your site, expand your GBP to capture\n                        takeaway searches, and close citation gaps to lift\n                        visibility across Brighton.\n                      </p>\n                      <div className=\"text-muted-foreground flex items-center gap-4 text-sm\">\n                        <span>5 insights</span>\n                        <span>28 recommendations</span>\n                      </div>\n                      <div>\n                        <Button dataHook=\"see-all-insights-button\">\n                          See all insights\n                          <Sparkles />\n                        </Button>\n                      </div>\n                    </div>\n                    <div className=\"flex flex-col items-center gap-2\" data-hook=\"location-score\">\n                      <span className=\"text-muted-foreground text-sm\">\n                        Location Score\n                      </span>\n                      <div className=\"relative size-36\">\n                        <svg viewBox=\"0 0 120 120\" className=\"size-full -rotate-90\">\n                          <circle\n                            cx=\"60\"\n                            cy=\"60\"\n                            r=\"52\"\n                            fill=\"none\"\n                            strokeWidth=\"10\"\n                            className=\"stroke-muted\"\n                          />\n                          <circle\n                            cx=\"60\"\n                            cy=\"60\"\n                            r=\"52\"\n                            fill=\"none\"\n                            strokeWidth=\"10\"\n                            strokeLinecap=\"round\"\n                            strokeDasharray=\"326.7\"\n                            strokeDashoffset={326.7 * (1 - 32 / 100)}\n                            className=\"stroke-orange-400\"\n                          />\n                        </svg>\n                        <div className=\"absolute inset-0 flex flex-col items-center justify-center\">\n                          <span className=\"font-display text-4xl font-semibold\">\n                            32\n                          </span>\n                          <span className=\"text-muted-foreground text-xs\">\n                            /100\n                          </span>\n                        </div>\n                      </div>\n                      <div className=\"text-muted-foreground flex gap-4 text-xs\">\n                        <span>Foundation 64/100</span>\n                        <span>Visibility 0/100</span>\n                      </div>\n                    </div>\n                  </div>\n                </CardContent>\n              </Card>\n\n              {/* Build your foundation */}\n              <div>\n                <TypographyH2 dataHook=\"foundation-title\">\n                  Build your foundation\n                </TypographyH2>\n                <p className=\"text-muted-foreground text-sm\">\n                  Your foundations are what impact how easily you get found\n                  online.\n                </p>\n              </div>\n              <div className=\"grid gap-6 lg:grid-cols-2\">\n                {/* foundation-metric-card recipe ×2 (copied; recipe file\n                    is the authoring source). */}\n                <Card variant=\"filled\" className=\"max-w-none\" dataHook=\"website-content-card\">\n                  <CardContent>\n                    <div className=\"flex flex-col gap-4\">\n                      <div className=\"flex items-center gap-2\">\n                        <Globe className=\"text-muted-foreground size-5\" />\n                        <span className=\"text-sm font-medium\">\n                          Website and content\n                        </span>\n                      </div>\n                      <div className=\"flex items-baseline gap-1\">\n                        <span className=\"text-3xl font-bold\">68</span>\n                        <span className=\"text-muted-foreground text-sm\">/100</span>\n                      </div>\n                      <div className=\"flex flex-col gap-3\">\n                        {WEBSITE_METRICS.map((m) => (\n                          <MetricRow key={m.id} {...m} />\n                        ))}\n                      </div>\n                    </div>\n                  </CardContent>\n                </Card>\n                <Card variant=\"filled\" className=\"max-w-none\" dataHook=\"gbp-card\">\n                  <CardContent>\n                    <div className=\"flex flex-col gap-4\">\n                      <div className=\"flex items-center gap-2\">\n                        <Store className=\"text-muted-foreground size-5\" />\n                        <span className=\"text-sm font-medium\">\n                          Google Business Profile\n                        </span>\n                      </div>\n                      <div className=\"flex items-baseline gap-1\">\n                        <span className=\"text-3xl font-bold\">54</span>\n                        <span className=\"text-muted-foreground text-sm\">/100</span>\n                      </div>\n                      <div className=\"flex flex-col gap-3\">\n                        {GBP_METRICS.map((m) => (\n                          <MetricRow key={m.id} {...m} />\n                        ))}\n                      </div>\n                    </div>\n                  </CardContent>\n                </Card>\n              </div>\n            </div>\n          </GlobalLayoutContentBody>\n        </GlobalLayoutContent>\n      </GlobalLayout>\n    </SidebarProvider>\n  );\n}"
  },
  {
    "id": "page-skeleton",
    "label": "Page Skeleton",
    "description": "Sidebar shell + location page header + content region, DS compounds throughout.",
    "source": "// Page Skeleton — Sidebar shell + location page header + content region, DS compounds throughout.\n//\n// Composed the way BrightLocal's own blocks-sidebar--default story does:\n// SidebarProvider > GlobalLayout > GlobalLayoutSidebar > Sidebar(...) +\n// GlobalLayoutContent > ContentHeader / ContentBody. No hand-rolled nav —\n// the sidebar body is the shipped Sidebar compound family. Nav content\n// matches the live logged-in dashboard (July 2026: Blackberry Farm Park /\n// Location Summary). The content body is a placeholder region to build on.\n// Edit freely; re-run `node scripts/generate-registry-templates.mjs`.\n\nimport {\n  Avatar,\n  AvatarFallback,\n  Badge,\n  Card,\n  CardContent,\n  GlobalLayout,\n  GlobalLayoutContent,\n  GlobalLayoutContentBody,\n  GlobalLayoutContentHeader,\n  GlobalLayoutSidebar,\n  Logo,\n  Separator,\n  Sidebar,\n  SidebarAccountDropdown,\n  SidebarContent,\n  SidebarFooter,\n  SidebarGroup,\n  SidebarGroupContent,\n  SidebarHeader,\n  SidebarMenu,\n  SidebarMenuButton,\n  SidebarMenuItem,\n  SidebarProvider,\n  SidebarTrigger,\n  TypographyH2,\n} from \"@brightlocal/ui-components\";\nimport {\n  Building,\n  Globe,\n  Grid3x3,\n  House,\n  LayoutDashboard,\n  Link,\n  Menu,\n  Sparkles,\n  Star,\n  Store,\n  TrendingUp,\n} from \"@brightlocal/icons\";\n\n// Sidebar nav icons: 20px (size-5), default stroke — the project's\n// curated convention (rules/05-product-map.md). Deliberately NOT the\n// live platform's 24px/1.33, which contradicts their own docs.\nconst TOP_ITEMS = [\n  { id: \"your-locations\", label: \"Your Locations\", icon: House },\n];\n\nconst LOCATION_ITEMS = [\n  {\n    id: \"location-summary\",\n    label: \"Location Summary\",\n    icon: LayoutDashboard,\n    active: true,\n  },\n  { id: \"ai-insights\", label: \"AI Insights\", icon: Sparkles },\n  { id: \"rankings\", label: \"Rankings\", icon: TrendingUp },\n  { id: \"local-search-grid\", label: \"Local Search Grid\", icon: Grid3x3 },\n  { id: \"citations\", label: \"Citations\", icon: Link },\n  { id: \"gbp\", label: \"GBP\", icon: Store },\n  { id: \"reputation-reviews\", label: \"Reputation & Reviews\", icon: Star },\n];\n\nconst TOOL_ITEMS = [\n  { id: \"location-manager\", label: \"Location Manager\", icon: Building },\n  { id: \"white-label\", label: \"White-label\", icon: Globe },\n];\n\nfunction NavGroup({ items }) {\n  return (\n    <SidebarGroup>\n      <SidebarGroupContent>\n        <SidebarMenu>\n          {items.map((item) => (\n            <SidebarMenuItem key={item.id}>\n              <SidebarMenuButton\n                dataHook={`nav-${item.id}`}\n                isActive={item.active}\n              >\n                {item.icon ? <item.icon className=\"size-5\" /> : null}\n                <span>{item.label}</span>\n              </SidebarMenuButton>\n            </SidebarMenuItem>\n          ))}\n        </SidebarMenu>\n      </SidebarGroupContent>\n    </SidebarGroup>\n  );\n}\n\nexport default function PageSkeleton() {\n  return (\n    <SidebarProvider dataHook=\"page-skeleton-sidebar-provider\" defaultOpen>\n      <GlobalLayout dataHook=\"global-layout\">\n        <GlobalLayoutSidebar dataHook=\"global-layout-sidebar\">\n          <Sidebar dataHook=\"app-sidebar\">\n            <SidebarHeader>\n              <Logo className=\"h-6\" dataHook=\"sidebar-logo\" />\n            </SidebarHeader>\n            <SidebarContent dataHook=\"sidebar-content\">\n              <NavGroup items={TOP_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-1\" />\n              <NavGroup items={LOCATION_ITEMS} />\n              <Separator spacing=\"md\" dataHook=\"sidebar-separator-2\" />\n              <NavGroup items={TOOL_ITEMS} />\n            </SidebarContent>\n            <SidebarFooter dataHook=\"sidebar-footer\">\n              {/* Account menu — the shipped SidebarAccountDropdown\n                  (name/email trigger + divider-grouped menu), mounted\n                  exactly as the DS's own story does. */}\n              <SidebarMenu>\n                <SidebarMenuItem>\n                  <SidebarAccountDropdown\n                    dataHook=\"sidebar-account-dropdown\"\n                    name=\"Andy Smith\"\n                    email=\"andy@acmecorp.com\"\n                    avatar={\n                      <Avatar dataHook=\"sidebar-user-avatar\">\n                        <AvatarFallback>AS</AvatarFallback>\n                      </Avatar>\n                    }\n                    menuGroups={[\n                      [\n                        { label: \"Account settings\" },\n                        { label: \"Notification preferences\" },\n                      ],\n                      [{ label: \"Log out\" }],\n                    ]}\n                    side=\"top\"\n                    align=\"end\"\n                  />\n                </SidebarMenuItem>\n              </SidebarMenu>\n            </SidebarFooter>\n          </Sidebar>\n        </GlobalLayoutSidebar>\n\n        <GlobalLayoutContent dataHook=\"global-layout-content\">\n          {/* Mobile top bar — the live platform's responsive shell: the\n              sidebar is hidden below lg, and this bar (hamburger + logo)\n              takes over. SidebarTrigger opens the DS's built-in mobile\n              sheet — no hand-rolled drawer. Menu (≡) matches the live\n              platform's icon; size-11 = 44px minimum touch target with\n              the size-5 glyph matching the sidebar nav icons. No border\n              — the live platform's mobile bar has no dividing line. */}\n          <header className=\"flex items-center gap-1 px-1 py-1 lg:hidden\">\n            <SidebarTrigger dataHook=\"mobile-sidebar-trigger\" className=\"size-11\">\n              <Menu className=\"size-5\" />\n            </SidebarTrigger>\n            <Logo className=\"h-6\" dataHook=\"mobile-logo\" />\n          </header>\n          {/* Page header — location identity */}\n          <GlobalLayoutContentHeader dataHook=\"page-header\">\n            <div className=\"flex min-w-0 items-center gap-3\">\n              <Avatar dataHook=\"location-avatar\">\n                <AvatarFallback>BF</AvatarFallback>\n              </Avatar>\n              <div className=\"min-w-0\">\n                <TypographyH2 dataHook=\"page-title\">\n                  Blackberry Farm Park\n                </TypographyH2>\n                <div className=\"text-muted-foreground flex flex-wrap items-center gap-2 text-sm\">\n                  <span>Lewes, BN8 6JD</span>\n                  <span>★ 4.3 (878 reviews)</span>\n                  <Badge dataHook=\"location-status\">Active</Badge>\n                </div>\n              </div>\n            </div>\n            <span className=\"text-muted-foreground shrink-0 text-sm\">\n              Last updated: 12/07/26\n            </span>\n          </GlobalLayoutContentHeader>\n\n          {/* Page content — placeholder region to build on */}\n          <GlobalLayoutContentBody dataHook=\"page-body\">\n            <div className=\"flex flex-col gap-6\">\n              <Card variant=\"filled\" className=\"max-w-none\" dataHook=\"content-primary-card\">\n                <CardContent>\n                  <p className=\"text-muted-foreground py-10 text-center text-sm\">\n                    Primary content — welcome card, score, insights.\n                  </p>\n                </CardContent>\n              </Card>\n              <div>\n                <TypographyH2 dataHook=\"section-title\">\n                  Section title\n                </TypographyH2>\n                <p className=\"text-muted-foreground text-sm\">\n                  One-line section description.\n                </p>\n              </div>\n              <div className=\"grid gap-6 sm:grid-cols-2\">\n                <Card variant=\"filled\" className=\"max-w-none\" dataHook=\"section-card-1\">\n                  <CardContent>\n                    <p className=\"text-muted-foreground py-10 text-center text-sm\">\n                      Section card\n                    </p>\n                  </CardContent>\n                </Card>\n                <Card variant=\"filled\" className=\"max-w-none\" dataHook=\"section-card-2\">\n                  <CardContent>\n                    <p className=\"text-muted-foreground py-10 text-center text-sm\">\n                      Section card\n                    </p>\n                  </CardContent>\n                </Card>\n              </div>\n            </div>\n          </GlobalLayoutContentBody>\n        </GlobalLayoutContent>\n      </GlobalLayout>\n    </SidebarProvider>\n  );\n}"
  },
  {
    "id": "sidebar-switcher",
    "label": "Sidebar Switcher",
    "description": "App shell with an account switcher (SidebarSwitcher) at the top and per-section collapsible submenus.",
    "source": "// Sidebar Switcher — App shell with an account switcher (SidebarSwitcher) at the top and per-section collapsible submenus.\n//\n// Sidebar proposal (July 2026): SidebarSwitcher in the header driving a\n// SidebarPopoverMenu of accounts, and each nav section rendered as a\n// SidebarMenuCollapsible whose bordered submenu expands for the selected\n// section. Composed the way blocks-sidebar--default and\n// blocks-sidebar-sidebarmenusubbutton--default do it: DS compounds only,\n// no hand-rolled nav. Hand-authored — safe from harvest re-runs (those\n// only rewrite blocks/ and sidecar bodies). Edit freely; re-run\n// `node scripts/generate-registry-templates.mjs`.\n\nimport {\n  Avatar,\n  AvatarFallback,\n  Badge,\n  Breadcrumb,\n  BreadcrumbItem,\n  BreadcrumbLink,\n  BreadcrumbList,\n  BreadcrumbPage,\n  BreadcrumbSeparator,\n  Card,\n  CardContent,\n  Chip,\n  GlobalLayout,\n  GlobalLayoutContent,\n  GlobalLayoutContentBody,\n  GlobalLayoutContentHeader,\n  GlobalLayoutSidebar,\n  Logo,\n  Sidebar,\n  SidebarAccountDropdown,\n  SidebarContent,\n  SidebarGroup,\n  SidebarGroupContent,\n  SidebarGroupLabel,\n  SidebarHeader,\n  SidebarMenu,\n  SidebarMenuButton,\n  SidebarMenuCollapsible,\n  SidebarMenuCollapsibleContent,\n  SidebarMenuCollapsibleTrigger,\n  SidebarMenuItem,\n  SidebarMenuSubButton,\n  SidebarMenuSubItem,\n  SidebarMenuSubVariant,\n  SidebarPopoverMenu,\n  SidebarProvider,\n  SidebarSeparator,\n  SidebarSwitcher,\n  SidebarTrigger,\n  TypographyH2,\n} from \"@brightlocal/ui-components\";\nimport {\n  BarChart3,\n  Briefcase,\n  Building,\n  Globe,\n  Grid3x3,\n  House,\n  Link,\n  ListChecks,\n  Menu,\n  SlidersHorizontal,\n  Sparkles,\n  Star,\n  Store,\n  TrendingUp,\n} from \"@brightlocal/icons\";\n \n// ─── Accounts for the switcher popover ─────────────────────────────\n// No shortcuts, no add-action: this is an account switcher, not a\n// command menu.\nconst ACCOUNTS = [\n  { label: \"Acme Local Agency\", icon: <Building className=\"size-4\" /> },\n  { label: \"Harbour & Co\", icon: <Building className=\"size-4\" /> },\n  { label: \"Northside Dental Group\", icon: <Building className=\"size-4\" /> },\n];\n\n// ─── Nav model — the new IA (July 2026). Three levels: section →\n// item → leaf. `paid` marks add-ons in the IA data (not rendered —\n// the '$' marker was spreadsheet notation, not UI); `active` opens the\n// trail; `goto: \"<screen name>\"` links a row to another screen\n// (STUDIO-FLOWS — the flow lives in this data, not in markup).\nconst SECTIONS = [\n  {\n    id: \"ai-insights\",\n    label: \"AI Insights\",\n    icon: Sparkles,\n    sub: [\n      { id: \"ai-insights-website-content\", label: \"Website and Content\" },\n      { id: \"ai-insights-google-business-profile\", label: \"Google Business Profile\" },\n      { id: \"ai-insights-reviews\", label: \"Reviews\" },\n      { id: \"ai-insights-citations\", label: \"Citations\" },\n      { id: \"ai-insights-export\", label: \"Export Report\" },\n    ],\n  },\n  { id: \"setup-tasks\", label: \"Set-up Tasks\", icon: ListChecks },\n  {\n    id: \"location-profile\",\n    label: \"Location Profile\",\n    icon: Building,\n    sub: [\n      { id: \"location-profile-connect\", label: \"Connect to Listing Platforms\" },\n      {\n        id: \"location-profile-core\",\n        label: \"Core Information\",\n        sub: [\n          { id: \"location-profile-general\", label: \"General Settings\" },\n          { id: \"location-profile-business\", label: \"Business Details\" },\n          { id: \"location-profile-google-business-tracking\", label: \"Google Business Tracking\" },\n          { id: \"location-profile-categories\", label: \"Categories\" },\n          { id: \"location-profile-hours\", label: \"Opening Hours\" },\n          { id: \"location-profile-about\", label: \"About the Business\" },\n          { id: \"location-profile-additional\", label: \"Additional Data\" },\n          { id: \"location-profile-images\", label: \"Image Management\" },\n          { id: \"location-profile-citation-builder-data\", label: \"Citation Builder Data\" },\n          { id: \"location-profile-alerts\", label: \"Email Alerts\" },\n        ],\n      },\n    ],\n  },\n  {\n    id: \"rankings\",\n    label: \"Rankings\",\n    icon: TrendingUp,\n    active: true,\n    sub: [\n      { id: \"rankings-positions\", label: \"Positions\" },\n      { id: \"rankings-table\", label: \"Rankings Table\", active: true },\n      { id: \"rankings-keyword-groups\", label: \"Keyword Groups\" },\n      { id: \"rankings-competitors\", label: \"Chosen Competitors\" },\n      {\n        id: \"rankings-settings\",\n        label: \"Settings\",\n        sub: [\n          { id: \"rankings-general\", label: \"General Settings\" },\n          { id: \"rankings-search\", label: \"Search Settings\" },\n          { id: \"rankings-advanced\", label: \"Advanced Settings\" },\n          { id: \"rankings-alerts\", label: \"Email Alerts\" },\n        ],\n      },\n    ],\n  },\n  {\n    id: \"local-search-grid\",\n    label: \"Local Search Grid\",\n    icon: Grid3x3,\n    sub: [\n      { id: \"local-search-grid-keyword-1\", label: \"Keyword phrase #1\" },\n      { id: \"local-search-grid-keyword-2\", label: \"Keyword phrase #2\" },\n      { id: \"local-search-grid-keyword-3\", label: \"Keyword phrase #3\" },\n      { id: \"local-search-grid-keyword-4\", label: \"Keyword phrase #4\" },\n      { id: \"local-search-grid-keyword-5\", label: \"Keyword phrase #5\" },\n      { id: \"local-search-grid-add\", label: \"Add more keywords\", paid: true },\n      { id: \"local-search-grid-settings\", label: \"Settings\" },\n    ],\n  },\n  {\n    id: \"citations\",\n    label: \"Citations\",\n    icon: Link,\n    sub: [\n      { id: \"citations-live\", label: \"Live Citations\" },\n      { id: \"citations-pending\", label: \"Pending Citations\" },\n      { id: \"citations-competitor\", label: \"Competitor Citations\" },\n      { id: \"citations-builder\", label: \"Citation Builder\", paid: true },\n    ],\n  },\n  { id: \"reviews\", label: \"Reviews\", icon: Star },\n  { id: \"gbp-manager\", label: \"GBP Manager\", icon: Store },\n  { id: \"website-seo\", label: \"Website SEO\", icon: Globe },\n  { id: \"google-analytics\", label: \"Google Analytics\", icon: BarChart3 },\n  { id: \"agency-tools\", label: \"Agency Tools\", icon: Briefcase },\n];\n\n// ─── AppLayoutShell (in-file layout component — see recipes/app-layout-shell.jsx) ───\n// Cancels GlobalLayout's baked-in p-section-sm + viewport p-1 (string\n// literals in the dist, not prop-overridable — rules/90-audit.md) and\n// exposes the layout explorations as props.\n// NOTE the --color-* doubles: the theme maps --color-sidebar-* from\n// --sidebar-* AT :ROOT, and var() inside a custom property resolves\n// where the property is DEFINED — so a mid-tree --sidebar-background\n// override never reaches utilities compiled to\n// var(--color-sidebar-background). Override BOTH prefixes; the\n// --color-* ones are what the compiled utilities actually read.\nfunction sidebarTone(bg, fg, accent, accentFg, border) {\n  return {\n    // Paint the background DIRECTLY: the desktop Sidebar never sets a\n    // background (bg-sidebar-background exists only in its mobile Sheet\n    // branch — verified against the 2.20.0 dist), so re-pointing the\n    // token alone recolors nothing. The container paints it instead.\n    backgroundColor: bg,\n    // Foreground still cascades via `color` inheritance, and the\n    // token doubles below drive the accent/hover/active utilities.\n    color: fg,\n    \"--sidebar-background\": bg,\n    \"--color-sidebar-background\": bg,\n    \"--sidebar-foreground\": fg,\n    \"--color-sidebar-foreground\": fg,\n    \"--sidebar-accent\": accent,\n    \"--color-sidebar-accent\": accent,\n    \"--sidebar-accent-foreground\": accentFg,\n    \"--color-sidebar-accent-foreground\": accentFg,\n    \"--sidebar-border\": border,\n    \"--color-sidebar-border\": border,\n  };\n}\n\n// Theme-aware pair: resolves via CSS light-dark(), which follows\n// color-scheme — the shell wires color-scheme to the .dark class\n// (schemeCss below), so every preset flips with Studio's mode toggle.\n// Without this the presets pinned LIGHT ramp steps and dark mode had\n// nothing left to flip (the semantic .dark overrides were bypassed).\nconst ld = (light, dark) => `light-dark(${light}, ${dark})`;\n\nconst SIDEBAR_TONES = {\n  default: {},\n  // Pure white panel — pairs with pageLayers \"raised\" (white nav +\n  // white cards on the green-grey canvas) and the flush frame's\n  // default border.\n  white: sidebarTone(\n    ld(\"var(--ds-tailwind-colors-base-white)\", \"var(--ds-tailwind-colors-neutral-900)\"),\n    ld(\"var(--ds-tailwind-colors-neutral-600)\", \"var(--ds-tailwind-colors-neutral-300)\"),\n    ld(\"var(--ds-tailwind-colors-neutral-100)\", \"var(--ds-tailwind-colors-neutral-800)\"),\n    ld(\"var(--ds-tailwind-colors-neutral-900)\", \"var(--ds-tailwind-colors-neutral-50)\"),\n    ld(\"var(--ds-colors-sidebar-border-light)\", \"var(--ds-colors-sidebar-border-dark)\"),\n  ),\n  // The grey/green light version: BL's neutral ramp IS green-tinted\n  // (#f2f7f3 etc.), so neutral-100 on the neutral-50 page reads as a\n  // subtle brand-adjacent panel rather than plain grey.\n  subtle: sidebarTone(\n    ld(\"var(--ds-tailwind-colors-neutral-100)\", \"var(--ds-tailwind-colors-neutral-950)\"),\n    ld(\"var(--ds-tailwind-colors-neutral-600)\", \"var(--ds-tailwind-colors-neutral-300)\"),\n    ld(\"var(--ds-tailwind-colors-neutral-200)\", \"var(--ds-tailwind-colors-neutral-800)\"),\n    ld(\"var(--ds-tailwind-colors-neutral-900)\", \"var(--ds-tailwind-colors-neutral-50)\"),\n    ld(\"var(--ds-colors-sidebar-border-light)\", \"var(--ds-colors-sidebar-border-dark)\"),\n  ),\n  dark: sidebarTone(\n    \"var(--ds-tailwind-colors-neutral-900)\",\n    \"var(--ds-tailwind-colors-neutral-200)\",\n    \"var(--ds-tailwind-colors-neutral-800)\",\n    \"var(--ds-tailwind-colors-neutral-50)\",\n    \"var(--ds-colors-sidebar-border-dark)\",\n  ),\n  brand: sidebarTone(\n    \"var(--ds-tailwind-colors-green-950)\",\n    \"var(--ds-tailwind-colors-green-200)\",\n    \"var(--ds-tailwind-colors-green-900)\",\n    \"var(--ds-tailwind-colors-green-100)\",\n    \"var(--ds-colors-sidebar-border-dark)\",\n  ),\n};\n\n// Frame presets — how the sidebar sits against the screen edge.\n// \"flush\" = hard against it; \"floating\" = lifted off it a little\n// (margin + rounded corners). Values live HERE as presets, not as\n// free-text instance props — tweak the preset, every screen follows.\nconst SIDEBAR_FRAMES = {\n  // `classes` = the Tailwind for the preset; `margin` also feeds the\n  // pinned top/height, which MUST stay inline style — the DS sets those\n  // inline on the aside, and classes can't beat inline styles.\n  flush: { margin: 0, classes: \"\" },\n  // shadow-sm lifts the panel off a near-white canvas — with the\n  // 50-step tint, the border alone doesn't carry the elevation.\n  floating: { margin: 12, classes: \"m-3 overflow-hidden rounded-2xl shadow-sm\" },\n};\n\n// Sidebar shadow presets — Tailwind's scale, switchable independently\n// of the frame. \"frame\" = whatever the frame preset ships (floating's\n// shadow-sm); anything else replaces it.\nconst SIDEBAR_SHADOWS = {\n  frame: null,\n  none: \"\",\n  sm: \"shadow-sm\",\n  md: \"shadow-md\",\n  lg: \"shadow-lg\",\n};\n\n// Page layer presets — the page-side counterpart of SIDEBAR_TONES:\n// re-point the PAGE tokens (canvas + card surface) on the layout root.\n// \"raised\": canvas on the subtlest green-grey (BL's neutral ramp is\n// green-tinted), cards lift to WHITE. Both var prefixes for the same\n// reason as the sidebar tones (utilities read --color-*; :root\n// indirections resolve where DEFINED). backgroundColor paints the\n// canvas directly — the body backdrop is set at :root and won't\n// follow a mid-tree var swap.\nconst PAGE_LAYERS = {\n  default: {},\n  // Canvas at neutral-50 (#fcfdfc — the faintest tint; neutral-100\n  // read too strong), cards pure white, muted UP to neutral-100 so\n  // filled surfaces sit between card and canvas.\n  raised: {\n    backgroundColor: ld(\"var(--ds-tailwind-colors-neutral-50)\", \"var(--ds-tailwind-colors-neutral-950)\"),\n    \"--background\": ld(\"var(--ds-tailwind-colors-neutral-50)\", \"var(--ds-tailwind-colors-neutral-950)\"),\n    \"--color-background\": ld(\"var(--ds-tailwind-colors-neutral-50)\", \"var(--ds-tailwind-colors-neutral-950)\"),\n    \"--card\": ld(\"var(--ds-tailwind-colors-base-white)\", \"var(--ds-tailwind-colors-neutral-900)\"),\n    \"--color-card\": ld(\"var(--ds-tailwind-colors-base-white)\", \"var(--ds-tailwind-colors-neutral-900)\"),\n    \"--muted\": ld(\"var(--ds-tailwind-colors-neutral-100)\", \"var(--ds-tailwind-colors-neutral-800)\"),\n    \"--color-muted\": ld(\"var(--ds-tailwind-colors-neutral-100)\", \"var(--ds-tailwind-colors-neutral-800)\"),\n  },\n};\n\n\n// ─── ShellTweaker — hidden, session-local demo controls ─────────────\n// Stakeholder-demo layer: reveals in the bottom-right corner (hover the\n// corner, or Alt+T) and OVERRIDES the shell's look knobs at runtime.\n// Two layers, two owners: literal props on <AppLayoutShell> are the\n// AUTHORED decision (the inspector edits those, they persist in the\n// screen source); tweaks live in component state — a viewer on a share\n// link can play freely and reload always returns to the authored look.\n// Chips mark overridden knobs; Reset drops back to authored. Plain\n// elements on purpose — this is prototype chrome, not proposal UI.\nfunction ShellTweakerPanel({ authored, tweaks, setTweaks }) {\n  const [open, setOpen] = React.useState(false);\n  React.useEffect(() => {\n    const onKey = (e) => {\n      if (e.altKey && (e.code === \"KeyT\" || e.key === \"t\" || e.key === \"T\")) {\n        e.preventDefault();\n        setOpen((o) => !o);\n      }\n      if (e.key === \"Escape\") setOpen(false);\n    };\n    window.addEventListener(\"keydown\", onKey);\n    return () => window.removeEventListener(\"keydown\", onKey);\n  }, []);\n  const ROWS = [\n    { key: \"sidebarTone\", label: \"Sidebar tone\", values: [\"default\", \"white\", \"subtle\", \"dark\", \"brand\"] },\n    { key: \"sidebarFrame\", label: \"Frame\", values: [\"flush\", \"floating\"] },\n    { key: \"sidebarShadow\", label: \"Shadow\", values: [\"frame\", \"none\", \"sm\", \"md\", \"lg\"] },\n    { key: \"pageLayers\", label: \"Page layers\", values: [\"default\", \"raised\"] },\n    { key: \"stickyHeader\", label: \"Sticky header\", values: [true, false] },\n  ];\n  const live = { ...authored, ...tweaks };\n  const dirty = Object.keys(tweaks).length > 0;\n  const set = (key, v) =>\n    setTweaks((prev) => {\n      const next = { ...prev };\n      if (v === authored[key]) delete next[key];\n      else next[key] = v;\n      return next;\n    });\n  return (\n    <div className=\"group fixed right-0 bottom-0 z-50 p-3\" data-slot=\"shell-tweaker\">\n      {open ? (\n        <div className=\"w-64 rounded-xl border border-[light-dark(var(--ds-tailwind-colors-neutral-100),var(--ds-tailwind-colors-neutral-800))] bg-[light-dark(var(--ds-tailwind-colors-base-white),var(--ds-tailwind-colors-neutral-900))] p-3 shadow-lg\">\n          <div className=\"mb-2 flex items-center justify-between\">\n            <span className=\"text-xs font-semibold\">Shell tweaks</span>\n            <span className=\"flex items-center gap-2\">\n              {dirty ? (\n                <button\n                  onClick={() => setTweaks({})}\n                  className=\"text-muted-foreground text-[11px] underline underline-offset-2\"\n                >\n                  Reset\n                </button>\n              ) : null}\n              <button\n                onClick={() => setOpen(false)}\n                aria-label=\"Close shell tweaks\"\n                className=\"text-muted-foreground text-sm leading-none\"\n              >\n                {\"\\u00d7\"}\n              </button>\n            </span>\n          </div>\n          {ROWS.map((row) => (\n            <div key={row.key} className=\"mb-2 last:mb-0\">\n              <div className=\"text-muted-foreground mb-1 flex items-center justify-between text-[11px]\">\n                <span>{row.label}</span>\n                {tweaks[row.key] !== undefined ? <span>tweaked</span> : null}\n              </div>\n              <div className=\"flex flex-wrap gap-1\">\n                {row.values.map((v) => (\n                  <button\n                    key={String(v)}\n                    onClick={() => set(row.key, v)}\n                    className={\n                      live[row.key] === v\n                        ? \"rounded-full bg-[light-dark(var(--ds-tailwind-colors-neutral-900),var(--ds-tailwind-colors-neutral-50))] px-2 py-0.5 text-[11px] text-[light-dark(white,var(--ds-tailwind-colors-neutral-900))]\"\n                        : \"rounded-full bg-[light-dark(var(--ds-tailwind-colors-neutral-50),var(--ds-tailwind-colors-neutral-800))] px-2 py-0.5 text-[11px] text-[light-dark(var(--ds-tailwind-colors-neutral-600),var(--ds-tailwind-colors-neutral-300))]\"\n                    }\n                  >\n                    {v === true ? \"on\" : v === false ? \"off\" : v}\n                  </button>\n                ))}\n              </div>\n            </div>\n          ))}\n        </div>\n      ) : (\n        <button\n          onClick={() => setOpen(true)}\n          aria-label=\"Open shell tweaks (Alt+T)\"\n          className=\"flex size-9 items-center justify-center rounded-full border border-[light-dark(var(--ds-tailwind-colors-neutral-100),var(--ds-tailwind-colors-neutral-800))] bg-[light-dark(var(--ds-tailwind-colors-base-white),var(--ds-tailwind-colors-neutral-900))] opacity-0 shadow-md transition-opacity duration-200 group-hover:opacity-100 focus-visible:opacity-100\"\n        >\n          <SlidersHorizontal className=\"size-4\" />\n        </button>\n      )}\n    </div>\n  );\n}\n\nfunction AppLayoutShell({\n  flush = true,\n  stickyHeader = false,\n  pinnedSidebar = true,\n  sidebarTone = \"white\",\n  // Carry the tone onto the MOBILE Sheet too. The Sheet portals to\n  // document.body — outside this tree — so container-level vars can't\n  // reach it; a scoped <style> targeting its data-sidebar/data-mobile\n  // marks does. Toggle off to keep mobile in the default light tone.\n  mobileTone = true,\n  // Content column cap. The DS's GlobalLayoutContent self-caps at\n  // breakpoint-lg and centres within the column, so pinning the\n  // sidebar to the edge does NOT make content run full-bleed — this\n  // knob just makes that cap adjustable (\"1280px\", \"none\", …).\n  // NOTE: GlobalLayoutContentHeader hardcodes its own breakpoint-lg\n  // max-width in the dist, so only the body follows a custom value.\n  contentMaxWidth,\n  // How the sidebar sits against the screen edge (desktop only — the\n  // aside is hidden below lg). Presets in SIDEBAR_FRAMES above.\n  sidebarFrame = \"floating\", // \"flush\" | \"floating\"\n  // Sidebar drop shadow — overrides the frame's own. Presets in\n  // SIDEBAR_SHADOWS. \"frame\" (default) defers to the frame preset.\n  sidebarShadow = \"frame\", // \"frame\" | \"none\" | \"sm\" | \"md\" | \"lg\"\n  // Optional 1px border around the sidebar container. Any CSS color —\n  // tokens welcome: \"var(--sidebar-border)\", \"var(--ds-tailwind-colors-neutral-200)\".\n  sidebarBorder,\n  // Page-wide layer treatment — canvas + card surface. Presets in\n  // PAGE_LAYERS above. \"raised\" = green-grey canvas, white cards.\n  pageLayers = \"raised\", // \"default\" | \"raised\"\n  sidebar,\n  header,\n  // Mobile top bar slot (hamburger + logo). Rendered FIRST inside the\n  // content column so it sits ABOVE the page header below lg — passing\n  // it via children put it underneath (July 2026 screenshot).\n  mobileBar,\n  children,\n  className,\n  // Render the hidden demo tweaker (corner hover / Alt+T). Turn off\n  // for screens where prototype chrome must not exist at all.\n  tweaker = true,\n  dataHook = \"app-layout\",\n}) {\n  // ─── Tweaker override layer (see ShellTweakerPanel above): literal\n  // props are the AUTHORED look; tweaks shadow them for this session\n  // only. Reassigning the params keeps every downstream reference\n  // (tone/frame/shadow/layers/sticky) reading the LIVE values.\n  const authored = { sidebarTone, sidebarFrame, sidebarShadow, pageLayers, stickyHeader };\n  const [tweaks, setTweaks] = React.useState({});\n  ({ sidebarTone, sidebarFrame, sidebarShadow, pageLayers, stickyHeader } = {\n    ...authored,\n    ...tweaks,\n  });\n\n  const flushClasses = flush\n    ? // Zero the baked padding for the desktop flush layout, but put a\n      // uniform p-4 BACK below lg — the sidebar is hidden there and the\n      // content column was hugging the screen edges on tablet/mobile.\n      \"[&>[data-radix-scroll-area-viewport]]:p-0! [&_[data-slot=app-layout-shell]]:p-0! [&_[data-slot=app-layout-shell]]:max-lg:p-4!\"\n    : \"\";\n  const frame = SIDEBAR_FRAMES[sidebarFrame] ?? SIDEBAR_FRAMES.flush;\n  const shadowOverride = SIDEBAR_SHADOWS[sidebarShadow] ?? null;\n  const frameClasses =\n    shadowOverride === null\n      ? frame.classes\n      : [frame.classes.replace(/\\bshadow-\\w+\\b/g, \"\").trim(), shadowOverride]\n          .filter(Boolean)\n          .join(\" \");\n  // Pinned/flush sidebars get a border BY DEFAULT — without a\n  // containing edge the horizontal rules float on the page. Floating\n  // frames have their own boundary (radius + lift). Explicit\n  // sidebarBorder overrides; \"transparent\" opts out.\n  const borderColor =\n    sidebarBorder ??\n    (sidebarFrame === \"flush\" ? \"var(--sidebar-border)\" : undefined);\n  const tone = SIDEBAR_TONES[sidebarTone] ?? {};\n  const layers = PAGE_LAYERS[pageLayers] ?? {};\n  // Raised layers: cards are WHITE (the layer re-points --card) with\n  // base/border (semantic --border → neutral-200 #E6EDE8, .dark flips\n  // it) and NO shadow — matches their Figma, where card elevation is\n  // border-only. NEEDED because the DS's own card-border token is\n  // TRANSPARENT (filled cards ship borderless — rules/90-audit.md).\n  // Shadows stay a SIDEBAR treatment (SIDEBAR_SHADOWS / the floating\n  // frame). Scoped <style> because border-color can't ride the --card\n  // token swap.\n  const layerCss =\n    pageLayers === \"raised\"\n      ? `[data-slot=\"card\"]{border-color:var(--border)}`\n      : \"\";\n  // color-scheme wiring for the ld() pairs above — .dark flips them.\n  const schemeCss = \":root{color-scheme:light}.dark{color-scheme:dark}\";\n  const mobileToneCss =\n    mobileTone && Object.keys(tone).length > 0\n      ? `[data-sidebar=\"sidebar\"][data-mobile=\"true\"]{${Object.entries(tone)\n          .map(([k, v]) => `${k === \"backgroundColor\" ? \"background-color\" : k}:${v}`)\n          .join(\";\")}}`\n      : \"\";\n  return (\n    <GlobalLayout\n      dataHook={dataHook}\n      // Selection stamp: GlobalLayout's inner div spreads rest props\n      // AFTER its own data-slot, so this overrides \"global-layout\" and\n      // the selection agent resolves clicks to AppLayoutShell.\n      data-slot=\"app-layout-shell\"\n      className={[flushClasses, className].filter(Boolean).join(\" \") || undefined}\n      // Pinned = at the actual browser edge: the DS's global-container\n      // centres the WHOLE app at max-width breakpoint-xl, guttering the\n      // sidebar away from the edge on wide screens. maxWidth is a real\n      // prop, so pinned mode disables it.\n      maxWidth={pinnedSidebar && flush ? \"none\" : undefined}\n      // Layer vars + canvas paint land on GlobalLayout's inner div via\n      // its rest-spread; every bg-background / bg-card / bg-muted\n      // inside resolves against them.\n      style={layers}\n    >\n      <style>{schemeCss + mobileToneCss + layerCss}</style>\n      {tweaker ? (\n        <ShellTweakerPanel authored={authored} tweaks={tweaks} setTweaks={setTweaks} />\n      ) : null}\n      <GlobalLayoutSidebar\n        dataHook={`${dataHook}-sidebar`}\n        // Tailwind for everything static (py-4 breathing room, frame\n        // preset classes, border width). Inline style only where it\n        // must be: pinned top/height override the DS's OWN inline\n        // values, and tone/border-color are dynamic.\n        className={[\n          \"pt-4\",\n          frameClasses,\n          borderColor ? (sidebarFrame === \"flush\" ? \"border-r\" : \"border\") : \"\",\n        ]\n          .filter(Boolean)\n          .join(\" \")}\n        style={{\n          ...(pinnedSidebar && flush\n            ? {\n                top: frame.margin,\n                height: `calc(100dvh - ${2 * frame.margin}px)`,\n              }\n            : {}),\n          ...(borderColor ? { borderColor } : {}),\n          ...tone,\n        }}\n      >\n        {sidebar}\n      </GlobalLayoutSidebar>\n      <GlobalLayoutContent\n        dataHook={`${dataHook}-content`}\n        maxWidth={contentMaxWidth}\n      >\n        {mobileBar}\n        {header ? (\n          <GlobalLayoutContentHeader\n            dataHook={`${dataHook}-header`}\n            // The header owns its padding — it must render identically\n            // sticky or not; stickiness only adds surface + border +\n            // pinning.\n            className={[\n              \"pt-6 pb-4\",\n              stickyHeader\n                ? \"bg-background sticky top-0 z-10 border-b\"\n                : \"\",\n            ]\n              .filter(Boolean)\n              .join(\" \")}\n          >\n            {header}\n          </GlobalLayoutContentHeader>\n        ) : null}\n        {children}\n      </GlobalLayoutContent>\n    </GlobalLayout>\n  );\n}\n\n\n/* Sub rows. A row with its own `sub` renders a NESTED disclosure —\n   trigger restyled via twMerge (h-7 px-2 rounded-md text-sm) to sit in\n   the sub rhythm instead of the top-level pill. NOTE: the nested\n   SidebarMenuCollapsible renders its own <li>, so it is NOT wrapped in\n   SidebarMenuSubItem (li>li). */\nfunction SubRows({ items }) {\n  return items.map((item) =>\n    item.sub ? (\n      <SidebarMenuCollapsible\n        key={item.id}\n        dataHook={`collapsible-${item.id}`}\n        defaultOpen={item.active}\n      >\n        <SidebarMenuCollapsibleTrigger\n          size=\"sm\"\n          className=\"h-7 rounded-md px-2 text-sm font-normal [&>span:last-of-type]:whitespace-normal!\"\n        >\n          <span>{item.label}</span>\n        </SidebarMenuCollapsibleTrigger>\n        <SidebarMenuCollapsibleContent\n          variant={SidebarMenuSubVariant.BORDER}\n          className=\"ml-2 items-stretch pr-0\"\n        >\n          <SubRows items={item.sub} />\n        </SidebarMenuCollapsibleContent>\n      </SidebarMenuCollapsible>\n    ) : (\n      <SidebarMenuSubItem key={item.id} dataHook={`sub-item-${item.id}`}>\n        <SidebarMenuSubButton\n          className=\"h-auto min-h-7 w-full py-1 [&>span:last-of-type]:whitespace-normal!\"\n          dataHook={`sub-btn-${item.id}`}\n          isActive={item.active}\n          data-grade-goto={item.goto}\n        >\n          <span>{item.label}</span>\n        </SidebarMenuSubButton>\n      </SidebarMenuSubItem>\n    ),\n  );\n}\n\nfunction NavSection({ section }) {\n  if (!section.sub) {\n    return (\n      <SidebarMenuItem>\n        <SidebarMenuButton\n          className=\"px-4 [&>span:last-of-type]:whitespace-normal!\"\n          dataHook={`nav-${section.id}`}\n          isActive={section.active}\n          data-grade-goto={section.goto}\n        >\n          <section.icon className=\"size-5\" />\n          <span>{section.label}</span>\n        </SidebarMenuButton>\n      </SidebarMenuItem>\n    );\n  }\n  return (\n    <SidebarMenuCollapsible\n      dataHook={`collapsible-${section.id}`}\n      defaultOpen={section.active}\n    >\n      <SidebarMenuCollapsibleTrigger\n        className=\"px-4 [&>span:last-of-type]:whitespace-normal!\"\n        tooltip={section.label}\n      >\n        <section.icon className=\"size-5\" />\n        <span>{section.label}</span>\n      </SidebarMenuCollapsibleTrigger>\n      {/* ml-8 (on-scale, ~the parent icon's centreline); items-stretch\n          + w-full make sub rows span the full width. */}\n      {/* ml-6: rail ≈ the icon centreline with the px-4/px-4 inset\n          split. pr-2 overrides the variant's baked pr-10 — 40px of\n          dead right padding per level was the truncation driver. */}\n      <SidebarMenuCollapsibleContent\n        variant={SidebarMenuSubVariant.BORDER}\n        className=\"ml-6 items-stretch pr-2\"\n      >\n        <SubRows items={section.sub} />\n      </SidebarMenuCollapsibleContent>\n    </SidebarMenuCollapsible>\n  );\n}\n\nexport default function App() {\n  const sidebar = (\n    <Sidebar dataHook=\"app-sidebar\">\n      {/* Logo-only header; the account switcher lives in the STUCK\n          footer with the signed-in row. pb-3 overrides the DS's\n          hardcoded pb-9. */}\n      {/* pl-6 keeps the logo on the tightened 24px icon line\n          (groups px-2 + buttons px-4); the DS default pl-8 assumed the\n          airier inset. */}\n      <SidebarHeader dataHook=\"sidebar-header\" className=\"pb-3 pl-6\">\n        <Logo className=\"h-6\" dataHook=\"sidebar-logo\" />\n      </SidebarHeader>\n\n      {/* Tight vertical rhythm: kill the DS's default gap between\n          groups and between menu items — the separators alone mark\n          the sections. */}\n      {/* pr-2 ALWAYS: the DS adds pr-2 only when the nav overflows\n          (hasOverflow in sidebar.tsx), so the whole nav nudged 8px left\n          the moment it became scrollable. Reserving the gutter\n          permanently keeps the width stable either way — cn dedupes the\n          double pr-2 when the DS adds its own. */}\n      <SidebarContent dataHook=\"sidebar-content\" className=\"gap-0 pt-1 pr-2\">\n        <SidebarGroup className=\"px-2 py-1\">\n          <SidebarGroupContent>\n            <SidebarMenu className=\"gap-0\">\n              {SECTIONS.map((section) => (\n                <NavSection key={section.id} section={section} />\n              ))}\n            </SidebarMenu>\n          </SidebarGroupContent>\n        </SidebarGroup>\n\n      </SidebarContent>\n\n      {/* STUCK footer — deliberately NOT SidebarFooter: that component\n          PORTALS itself into the content scroll area (SidebarContent's\n          mt-auto portal target), so with an overflowing nav it scrolls\n          away with the content. A plain sibling of the scroll area is\n          always pinned. px-2 matches the nav groups' inset. Upstream\n          ask: SidebarFooter needs a non-portalling/sticky option. */}\n      <div\n        data-hook=\"sidebar-footer\"\n        className=\"border-sidebar-border flex shrink-0 flex-col gap-0.5 border-t px-2 py-1.5\"\n      >\n        {/* Account switcher — full-width row above the signed-in user. */}\n        {/* No trigger icon — the label carries it; the popover items\n            keep theirs for scanability. */}\n        <SidebarSwitcher\n          dataHook=\"account-switcher\"\n          label=\"Acme Local Agency\"\n          triggerAriaLabel=\"Switch account\"\n          triggerClassName=\"w-full px-2 py-1 [&>span]:flex-1 [&>span]:text-left [&>svg:last-child]:size-3 [&>svg:last-child]:opacity-100\"\n        >\n          <SidebarPopoverMenu\n            dataHook=\"account-switcher-menu\"\n            groupTitle=\"Accounts\"\n            items={ACCOUNTS}\n          />\n        </SidebarSwitcher>\n        <SidebarMenu>\n          {/* The dropdown trigger inherits SidebarMenuButton's baked\n              px-6 (rounded-full nav sizing) — comically wide in a\n              compact footer, and the DS plumbs no className through.\n              Target its data-hook from the item instead. */}\n          <SidebarMenuItem className=\"[&_[data-hook=sidebar-account-dropdown-button]]:px-2 [&_[data-hook=sidebar-account-dropdown-button]]:py-1\">\n            {/* `email` renders as span CHILDREN in the dist, so it\n                takes an entity — the plan/trial line rides there (plain\n                text; a Chip proved too loud for the footer). Upstream\n                ask: rename to a typed `meta` ReactNode slot. */}\n            <SidebarAccountDropdown\n              dataHook=\"sidebar-account-dropdown\"\n              name=\"Joe Bloggs\"\n              email=\"Trial: 14 days left\"\n              avatar={\n                <Avatar dataHook=\"sidebar-user-avatar\">\n                  <AvatarFallback className=\"bg-sidebar-accent text-sidebar-accent-foreground\">\n                    JB\n                  </AvatarFallback>\n                </Avatar>\n              }\n              menuGroups={[\n                [\n                  { label: \"Account Details\" },\n                  { label: \"Billing Details\" },\n                  { label: \"Addons\" },\n                  { label: \"Support Tickets\" },\n                ],\n                [{ label: \"Logout\" }],\n              ]}\n              side=\"top\"\n              align=\"end\"\n            />\n          </SidebarMenuItem>\n        </SidebarMenu>\n      </div>\n    </Sidebar>\n  );\n\n  // Page header — the page-header-with-breadcrumbs recipe: trail above\n  // the title, meta row below, no avatar. (There is no PageHeader\n  // component in the DS — the page header IS this composition.)\n  const header = (\n    <div className=\"flex min-w-0 flex-col gap-1\">\n      {/* Trail RULE: ANCESTORS ONLY, max two — the current page never\n          appears in the breadcrumb (the H2 below IS the current page).\n          BreadcrumbPage is deliberately unused. */}\n      <Breadcrumb dataHook=\"page-breadcrumb\">\n        <BreadcrumbList>\n          <BreadcrumbItem>\n            <BreadcrumbLink href=\"#\">Your Locations</BreadcrumbLink>\n          </BreadcrumbItem>\n          <BreadcrumbSeparator />\n          <BreadcrumbItem>\n            <BreadcrumbLink href=\"#\">Blackberry Farm Park</BreadcrumbLink>\n          </BreadcrumbItem>\n        </BreadcrumbList>\n      </Breadcrumb>\n      <TypographyH2 dataHook=\"page-title\">Monitor Reviews</TypographyH2>\n      <div className=\"text-muted-foreground flex flex-wrap items-center gap-2 text-sm\">\n        <span>Blackberry Farm Park — Lewes, BN8 6JD</span>\n        <Badge dataHook=\"location-status\">Active</Badge>\n      </div>\n    </div>\n  );\n\n  return (\n    <SidebarProvider dataHook=\"switcher-sidebar-provider\" defaultOpen>\n      {/* Layout knobs are LITERAL props so the inspector can edit them —\n          select the shell (click the page background) and flip\n          flush / stickyHeader / pinnedSidebar / sidebarTone. */}\n      <AppLayoutShell\n        flush={true}\n        stickyHeader={true}\n        pinnedSidebar={true}\n        sidebarTone=\"default\"\n        sidebar={sidebar}\n        header={header}\n        mobileBar={\n          <header className=\"flex items-center gap-1 px-1 py-1 lg:hidden\">\n            <SidebarTrigger dataHook=\"mobile-sidebar-trigger\" className=\"size-11\">\n              <Menu className=\"size-5\" />\n            </SidebarTrigger>\n            <Logo className=\"h-6\" dataHook=\"mobile-logo\" />\n          </header>\n        }\n        dataHook=\"app-layout\"\n      >\n        <GlobalLayoutContentBody dataHook=\"page-body\">\n          <Card variant=\"filled\" className=\"max-w-none\" dataHook=\"content-placeholder\">\n            <CardContent>\n              <p className=\"text-muted-foreground py-16 text-center text-sm\">\n                Content region — tall on purpose so the sticky header and\n                pinned sidebar are visible while scrolling.\n              </p>\n              {/* Height-only spacer — an earlier bg-muted version painted a\n                  huge neutral-100 rectangle that read as \"the canvas is\n                  too strong\". */}\n              <div className=\"h-[1200px]\" />\n            </CardContent>\n          </Card>\n        </GlobalLayoutContentBody>\n      </AppLayoutShell>\n    </SidebarProvider>\n  );\n}"
  }
] as const;
